import"./chunk-ZW5NV4UO.js";var e={en:{title:"Gardening and houseplants on Mastodon: people and tags to follow",description:"Grow a Mastodon feed full of gardens and houseplants. Find growers, plant care, succulents, greenhouses and hydroponics, then preview their posts.",heading:"Gardening and houseplants on Mastodon",listTitle:"Gardening and houseplants",intro:["A windowsill full of succulents, a greenhouse experiment or a border coming into bloom: follow people sharing what they grow and how they care for it. Ornamental gardens, indoor plants and home vegetable patches all belong here.","Choose people and hashtags, then preview their public posts. Useful plant subjects stay on the list even when their tags are quiet, so you can follow the things you want to see grow."],faq:[{q:"Do I need an account?",a:"You can browse and preview public posts without an account. Sign in with your Mastodon account to follow people and hashtags or create a list."},{q:"Does this include greenhouses and hydroponics?",a:"Yes, along with houseplant care, propagation, decorative gardens and home food growing. Farming and animal husbandry are outside this selection. Some useful tags are quiet, while others have unrelated posts or ads; preview them to choose your mix."},{q:"How do I get onto this list?",a:"Share gardening or houseplant posts regularly and allow your server to suggest your profile. Recent activity, sustained topic fit and review determine the selection. For help or removal, contact @mawkingbird@mastodon.social."}]},de:{title:"Garten und Zimmerpflanzen auf Mastodon: Menschen und Hashtags",description:"Entdecke Menschen, die g\xE4rtnern, Zimmerpflanzen pflegen und mit Gew\xE4chshaus oder Hydrokultur experimentieren. Stell deinen Feed zusammen und teste die Vorschau.",heading:"Garten und Zimmerpflanzen auf Mastodon",listTitle:"Garten und Zimmerpflanzen",intro:["Kakteen auf der Fensterbank, neue Triebe im Gew\xE4chshaus oder ein Beet voller Bl\xFCten: Hier teilen Menschen ihre Pflanzenfreude und ihre Erfahrungen beim G\xE4rtnern. Auch der kleine Gem\xFCsegarten geh\xF6rt dazu.","W\xE4hle Menschen und Hashtags aus und schau dir die \xF6ffentlichen Beitr\xE4ge in der Vorschau an. N\xFCtzliche Pflanzenthemen bleiben auch dann ausw\xE4hlbar, wenn unter dem Hashtag gerade wenig los ist."],faq:[{q:"Brauche ich ein Konto?",a:"Zum St\xF6bern und f\xFCr die Vorschau \xF6ffentlicher Beitr\xE4ge brauchst du kein Konto. Um Menschen und Hashtags zu folgen oder eine Liste anzulegen, meldest du dich mit deinem Mastodon-Konto an."},{q:"Sind Gew\xE4chsh\xE4user und Hydrokultur dabei?",a:"Ja, ebenso Zimmerpflanzen, Vermehrung, Zierg\xE4rten und Gem\xFCseanbau im eigenen Garten. Landwirtschaft und Tierhaltung geh\xF6ren nicht zu dieser Auswahl. Manche Hashtags sind ruhig, andere enthalten Werbung oder fremde Themen. Mit der Vorschau findest du deine Mischung."},{q:"Wie komme ich auf diese Liste?",a:"Schreib regelm\xE4\xDFig \xFCber deinen Garten oder Zimmerpflanzen und erlaube deinem Server, dein Profil vorzuschlagen. Aktuelle Aktivit\xE4t, dauerhafter Themenbezug und die Pr\xFCfung z\xE4hlen. Bei Fragen oder f\xFCr eine Entfernung erreichst du @mawkingbird@mastodon.social."}]},fr:{title:"Jardinage et plantes d\u2019int\xE9rieur sur Mastodon : qui suivre",description:"Compose ton fil Mastodon autour du jardinage et des plantes d\u2019int\xE9rieur : succulentes, serres, hydroponie et conseils de culture. Essaie l\u2019aper\xE7u.",heading:"Jardinage et plantes d\u2019int\xE9rieur sur Mastodon",listTitle:"Jardinage et plantes",intro:["Des succulentes sur le rebord de la fen\xEAtre, des boutures qui prennent ou un massif en fleurs : d\xE9couvre des personnes qui partagent leurs cultures et leurs exp\xE9riences. Plantes d\u2019int\xE9rieur, jardins d\u2019ornement et petits potagers ont leur place ici.","Choisis des comptes et des hashtags, puis explore leurs publications publiques dans l\u2019aper\xE7u. Les th\xE8mes utiles restent propos\xE9s m\xEAme quand leur hashtag est peu actif, pour que tu puisses suivre ce qui t\u2019int\xE9resse."],faq:[{q:"Faut-il un compte ?",a:"Tu peux parcourir la s\xE9lection et lire les publications publiques dans l\u2019aper\xE7u sans compte. Connecte-toi avec ton compte Mastodon pour suivre des personnes et des hashtags ou cr\xE9er une liste."},{q:"Les serres et l\u2019hydroponie sont-elles incluses ?",a:"Oui, avec les soins des plantes, la multiplication, les jardins d\u2019ornement et le potager familial. L\u2019agriculture et l\u2019\xE9levage sont hors sujet ici. Certains hashtags sont peu actifs, d\u2019autres contiennent de la publicit\xE9 ou des publications sans rapport. L\u2019aper\xE7u t\u2019aide \xE0 choisir."},{q:"Comment appara\xEEtre sur cette liste ?",a:"Publie r\xE9guli\xE8rement sur le jardinage ou les plantes d\u2019int\xE9rieur et autorise ton serveur \xE0 sugg\xE9rer ton profil. L\u2019activit\xE9 r\xE9cente, la r\xE9gularit\xE9 du sujet et la v\xE9rification comptent aussi. Pour une question ou un retrait, contacte @mawkingbird@mastodon.social."}]}};export{e as COPY};
